mapper.select:
SELECT * FROM t_heart_beat_record
AND TO_CHAR(heart_beat_time, 'YYYY-MM-DD') >= #{query.startDate}
AND TO_CHAR(heart_beat_time, 'YYYY-MM-DD') <= #{query.endDate}
AND (project_path ILIKE CONCAT('%', #{query.keywords}, '%') OR server_ip ILIKE CONCAT('%', #{query.keywords}, '%') OR process_no ILIKE CONCAT('%', #{query.keywords}, '%'))
order by heart_beat_time desc
